from functools import lru_cache

def max_expected_score(n, k):
    @lru_cache(None)
    def dp(rolls_left, current_sum):
        if rolls_left == 1:
            return (current_sum + sum(range(1, n+1))) / n
        else:
            expected = 0
            for i in range(1, n+1):
                expected += (i * dp(rolls_left - 1, current_sum + i))
            return expected / n

    return dp(k, 0)

